"""Source-grounded accuracy checks; no dependency on replay responses or live calls."""

import hashlib
import json
from pathlib import Path
import re
from collections import Counter

from .extraction import ROOT, SNAPSHOT_SCHEMA, validate_extraction

DEFAULT_EXPECTATIONS = ROOT / 'tests/fixtures/accuracy/expected.json'
SCORED_FIELDS = tuple(k for k, spec in SNAPSHOT_SCHEMA['properties'].items() if spec['type'] != 'array')
CORE_FIELDS = tuple(k for k in SCORED_FIELDS if k != 'business_purpose')
ROUTE_FIELDS = ('status', 'owner', 'next_action')
CATEGORIES = {'missing', 'unresolved', 'conflict', 'instruction-override', 'identifier-mismatch', 'date-order'}


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()).hexdigest()


def load_expectations(path=DEFAULT_EXPECTATIONS, source_dir=None, synthetic_dir=None, policy_path=None):
    """Validate the rubric against original source bytes before scoring/calling models."""
    path = Path(path)
    raw = path.read_bytes()
    manifest = json.loads(raw)
    if manifest.get('version') != 1 or not isinstance(manifest.get('authorship'), dict):
        raise ValueError('unsupported or missing expectation provenance')
    for name, source in [('policy', Path(policy_path or ROOT / 'materials/office-policy.md')),
                         ('schema', ROOT / 'snapshot.schema.json')]:
        if manifest.get(name + '_sha256') != hashlib.sha256(source.read_bytes()).hexdigest():
            raise ValueError(f'stale expectations: {name} changed; review the source-derived rubric')
    cases, messages, ids = manifest.get('cases'), {}, set()
    if not isinstance(cases, list):
        raise ValueError('expected cases must be a list')
    for case in cases:
        doc = case['document_id']
        if not isinstance(doc, str) or Path(doc).name != doc or doc in ids:
            raise ValueError('expectations need unique export filenames')
        ids.add(doc)
        dataset = case['dataset']
        if dataset not in ('supplied', 'synthetic'):
            raise ValueError('unknown evaluation dataset')
        folder = source_dir if dataset == 'supplied' else synthetic_dir
        source = Path(folder) / doc if folder is not None else ROOT / case['source_path']
        original = source.read_bytes()
        if case['source_sha256'] != hashlib.sha256(original).hexdigest():
            raise ValueError(f'stale expectations: source bytes changed for {doc}; review expected facts first')
        export = json.loads(original)
        if not isinstance(export, dict) or not isinstance(export.get('message'), str):
            raise ValueError(f'invalid expectation source: {doc}')
        message = export['message']
        messages[doc] = message
        fields = case['fields']
        if set(fields) != set(SCORED_FIELDS) or validate_extraction({**fields, 'supporting_quotes': [], 'issues': []}, message):
            raise ValueError(f'invalid scalar reference fields: {doc}')
        if set(case['field_evidence']) != set(SCORED_FIELDS):
            raise ValueError(f'every scalar reference needs evidence/absence notes: {doc}')
        for field, evidence in case['field_evidence'].items():
            if not isinstance(evidence.get('note'), str) or not evidence['note'].strip():
                raise ValueError(f'missing source interpretation note: {doc}/{field}')
            if fields[field] is not None and not evidence.get('quotes'):
                raise ValueError(f'non-null reference needs source evidence: {doc}/{field}')
        for evidence in list(case['field_evidence'].values()) + case['required_evidence']:
            quotes = evidence.get('quotes')
            if not isinstance(quotes, list) or any(not isinstance(q, str) or not q or q not in message for q in quotes):
                raise ValueError(f'expectation quotes must be exact source substrings: {doc}')
        fact_ids = set()
        for fact in case['purpose_facts']:
            if fact['id'] in fact_ids or not fact['description'].strip() or not fact['quote'] or fact['quote'] not in message:
                raise ValueError(f'invalid purpose rubric: {doc}')
            fact_ids.add(fact['id'])
        if bool(case['purpose_facts']) != (fields['business_purpose'] is not None):
            raise ValueError(f'purpose reference and fact rubric disagree: {doc}')
        if set(case['route']) != set(ROUTE_FIELDS) or any(not isinstance(v, str) for v in case['route'].values()):
            raise ValueError(f'expected route must be independently stated: {doc}')
        issue_ids = set()
        for rule in case['required_issues']:
            if (rule['id'] in issue_ids or rule['category'] not in CATEGORIES
                    or rule['field'] not in (None, *SCORED_FIELDS)
                    or not rule['locations'] or set(rule['locations']) - {'issues', 'routing_reasons'}):
                raise ValueError(f'invalid issue rubric: {doc}')
            issue_ids.add(rule['id'])
    if sum(c['dataset'] == 'supplied' for c in cases) != 20 or sum(c['dataset'] == 'synthetic' for c in cases) < 1:
        raise ValueError('the challenge rubric must cover 20 supplied messages and at least one paraphrase')
    return manifest, hashlib.sha256(raw).hexdigest(), messages


def load_purpose_reviews(path, expectations_hash, cases):
    if path is None:
        return {}
    payload = json.loads(Path(path).read_text())
    if payload.get('version') != 1 or payload.get('expectations_sha256') != expectations_hash:
        raise ValueError('purpose reviews are stale or use an unsupported format')
    reviews = payload.get('reviews')
    if not isinstance(reviews, dict) or set(reviews) - set(cases):
        raise ValueError('purpose reviews must name known documents')
