"use strict";
const $ = id => document.getElementById(id);
const labels = {review:"For review", "needs-information":"Needs information", error:"Processing error"};
const actions = {"review-request":"Review request", "review-risk-then-owner":"Review risk, then send to system owner", clarify:"Ask the requester for clarification", "confirm-withdrawal":"Confirm withdrawal", "inspect-message":"Inspect the embedded instructions", "retry-extraction":"Retry extraction using the CLI"};
let state = null, filter = "all", refreshing = false;
function node(tag, text, className) {
  const result = document.createElement(tag);
  if (text !== undefined) result.textContent = text;
  if (className) result.className = className;
  return result;
}
function notice(text) { $("banner").textContent = text || ""; $("banner").hidden = !text; }
function cell(text, subtext, className) {
  const td = node("td"); td.append(node("span", text, className));
  if (subtext) td.append(node("span", subtext, "subtext"));
  return td;
}
function renderRows() {
  if (!state) return;
  const search = $("search").value.trim().toLowerCase(), owner = $("owner").value;
  const rows = state.requests.filter(r => {
    const e = r.extraction || {};
    return (filter === "all" || r.status === filter) && (!owner || r.owner === owner) &&
      [r.document_id,e.request_id,e.requester,e.team,e.system,e.manager].some(v => String(v || "").toLowerCase().includes(search));
  });
  $("rows").replaceChildren();
  for (const r of rows) {
    const e = r.extraction || {}, tr = node("tr"), id = node("td");
    const open = node("button", r.document_id.replace(/\.json$/, ""), "request-id");
    open.addEventListener("click", () => showDetails(r)); id.append(open, node("span", e.request_date || "Date unresolved", "subtext")); tr.append(id);
    tr.append(cell(e.requester || "Unresolved", e.team, "person"));
    tr.append(cell(e.system || "Unresolved", e.environment || "Environment unresolved"));
    const access = node("td"); access.append(node("span", e.permission || "Unresolved", "permission " + (e.permission || ""))); tr.append(access);
    const status = node("td"); status.append(node("span", labels[r.status] || r.status, "pill " + r.status)); tr.append(status);
    tr.append(cell(r.owner, actions[r.next_action] || r.next_action));
    const arrow = node("td"), button = node("button", "›", "detail-arrow");
    button.setAttribute("aria-label", "View " + r.document_id); button.addEventListener("click", () => showDetails(r)); arrow.append(button); tr.append(arrow);
    $("rows").append(tr);
  }
  if (!rows.length) { const tr = node("tr"), td = node("td", state.requests.length ? "No requests match your filters." : "No requests yet. Run intake to prepare your review queue.", "empty"); td.colSpan = 7; tr.append(td); $("rows").append(tr); }
  $("showing").textContent = `Showing ${rows.length} of ${state.requests.length} requests`;
}
function showDetails(r) {
  const body = $("detail-body"), e = r.extraction || {}; body.replaceChildren();
  const title = node("h2", r.document_id.replace(/\.json$/, "")); title.id = "detail-title"; body.append(title);
  const route = node("div", undefined, "route-card");
  route.append(node("strong", r.owner), node("p", actions[r.next_action] || r.next_action)); body.append(route);
  body.append(node("span", labels[r.status] || r.status, "pill " + r.status));
  const facts = node("dl", undefined, "facts");
  const names = {request_id:"Stated request ID",request_date:"Request date",kind:"Request type",requester:"Requester",team:"Team",system:"System",environment:"Environment",permission:"Requested permission",start_date:"Start date",end_date:"End date",manager:"Manager contact",business_purpose:"Business purpose"};
  for (const [field,label] of Object.entries(names)) {
    const item = node("div", undefined, field === "business_purpose" ? "wide" : "");
    item.append(node("dt", label), node("dd", e[field] === null || e[field] === undefined ? "Unresolved — see issues below" : e[field])); facts.append(item);
  }
  body.append(facts);
  if (r.error) body.append(node("p", r.error, "issue"));
  const issues = [...new Set([...(e.issues || []), ...(r.routing_reasons || [])])];
  if (issues.length) { body.append(node("h3", "Review notes")); for (const issue of issues) body.append(node("p", issue, "issue")); }
  body.append(node("h3", "Source evidence"));
  for (const quote of e.supporting_quotes || []) body.append(node("blockquote", quote, "quote"));
  if (!e.supporting_quotes?.length) body.append(node("p", "No supporting quotes were recorded.", "subtext"));
  const source = node("details", undefined, "source-reference");
  source.append(node("summary", "Source reference & provenance"), node("code", `${r.document_id}\nSHA-256: ${r.source_sha256 || "Unavailable"}\nResponse source: ${r.response_source}`)); body.append(source);
  $("details").showModal();
}
