"""Local browser dashboard using the same durable intake engine as the CLI."""

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import threading
from urllib.parse import urlsplit

from .fixtures import fixture_response

ASSETS = Path(__file__).parent / "static"
PUBLIC_FIELDS = ("document_id", "source_sha256", "extraction", "status", "owner",
                 "next_action", "error", "response_source", "routing_reasons")


class Dashboard:
    def __init__(self, app, workers=4):
        self.app, self.workers = app, workers
        self.lock = threading.Lock()
        self.running = False
        self.batch_id = None
        self.task_error = None
        if not (app.output / "CURRENT.json").exists():
            # Honor committed results on a fresh checkout without model calls.
            if (app.output / "extractions.jsonl").exists() and not app.current():
                app.import_legacy()
            else:
                app.publish()

    def state(self):
        records, queue = self.app.snapshot()
        with self.lock:
            batch, running, error = self.batch_id, self.running, self.task_error
        if batch is None:
            batches = self.app.store.batches()
            batch = batches[0]["id"] if batches else None
        return {"requests": [{k: r.get(k) for k in PUBLIC_FIELDS} for r in records],
                "generation": queue["generation_id"], "updated_at": queue["generated_at"],
                "mock": self.app.extractor.config["provider"] == "mock",
                "model": self.app.extractor.config["model"], "running": running,
                "batch_id": batch, "progress": self.app.status(batch) if batch else None,
                "task_error": error}

    def start(self):
        with self.lock:
            if self.running:
                raise RuntimeError("An intake is already running. Completed results remain available below.")
            self.batch_id = self.app.submit()
            self.running, self.task_error = True, None
            batch = self.batch_id
            threading.Thread(target=self._run, args=(batch,), daemon=True).start()
            return batch

    def _run(self, batch):
        try:
            mock = self.app.extractor.config["provider"] == "mock"
            self.app.resume(batch, workers=self.workers,
                            responder=fixture_response if mock else None,
                            response_source="mock" if mock else None)
        except Exception:
            with self.lock:
                self.task_error = "Intake was interrupted. Inspect status and resume the saved batch using the CLI."
        finally:
            with self.lock:
                self.running = False


def create_server(app, host="127.0.0.1", port=8080, workers=4):
    if host not in ("127.0.0.1", "localhost"):
        raise ValueError("the browser dashboard supports local loopback hosts only")
    if workers <= 0:
        raise ValueError("workers must be positive")
    dashboard = Dashboard(app, workers)

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass  # Request paths and bodies need not enter operational logs.

        def send(self, status, body, content_type="application/json; charset=utf-8"):
            if isinstance(body, dict):
                body = json.dumps(body, ensure_ascii=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; object-src 'none'; frame-ancestors 'none'; base-uri 'none'")
            self.end_headers()
            self.wfile.write(body)

        def valid_host(self):
            port = self.server.server_port
            return self.headers.get("Host") in (f"127.0.0.1:{port}", f"localhost:{port}")

        def do_GET(self):
            if not self.valid_host():
                return self.send(403, {"error": "Use the dashboard's localhost URL."})
            path = urlsplit(self.path).path
            if path == "/api/state":
                try:
                    return self.send(200, dashboard.state())
                except Exception:
                    return self.send(503, {"error": "Queue unavailable. Retry or run python -m intake export."})
            assets = {"/": ("index.html", "text/html; charset=utf-8"),
                      "/assets/app.js": ("app.js", "text/javascript; charset=utf-8"),
                      "/assets/style.css": ("style.css", "text/css; charset=utf-8")}
            if path not in assets:
                return self.send(404, {"error": "Not found"})
            name, content_type = assets[path]
            self.send(200, (ASSETS / name).read_bytes(), content_type)

        def do_POST(self):
            if not self.valid_host() or self.headers.get("Origin", "http://" + self.headers.get("Host", "")) != "http://" + self.headers.get("Host", ""):
                return self.send(403, {"error": "Cross-origin actions are not allowed."})
            if urlsplit(self.path).path != "/api/intake":
                return self.send(404, {"error": "Not found"})
            if self.headers.get("Content-Type", "").split(";")[0].strip() != "application/json":
                return self.send(415, {"error": "Expected application/json."})
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if not 0 < size <= 1024:
                    return self.send(400, {"error": "Expected a small JSON object."})
                if not isinstance(json.loads(self.rfile.read(size)), dict):
                    raise ValueError()
            except (ValueError, UnicodeError):
                return self.send(400, {"error": "Expected a JSON object."})
            try:
                return self.send(202, {"batch_id": dashboard.start()})
            except RuntimeError as exc:
                return self.send(409, {"error": str(exc)})
            except Exception:
                return self.send(503, {"error": "Could not start intake. Check the configured source directory and CLI status."})

    server = ThreadingHTTPServer((host, port), Handler)
    server.dashboard = dashboard
    return server


def serve(app, host="127.0.0.1", port=8080, workers=4):
    with create_server(app, host, port, workers) as server:
        print(f"Review queue: http://{host}:{server.server_port}", flush=True)
        print("Press Ctrl+C to stop the local dashboard.", flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass

